ALTER TABLE "game_actions" DROP CONSTRAINT "game_actions_decision_check";--> statement-breakpoint
ALTER TABLE "game_actions" ADD CONSTRAINT "game_actions_decision_check" CHECK (("game_actions"."status" = 'SUBMITTED' AND "game_actions"."decided_at" IS NULL AND "game_actions"."decided_by_session_id" IS NULL AND "game_actions"."rejection_reason" IS NULL) OR ("game_actions"."status" = 'CONFIRMED' AND "game_actions"."decided_at" IS NOT NULL AND "game_actions"."rejection_reason" IS NULL) OR ("game_actions"."status" IN ('REJECTED', 'CANCELLED') AND "game_actions"."decided_at" IS NOT NULL AND "game_actions"."decided_by_session_id" IS NOT NULL AND length(btrim("game_actions"."rejection_reason")) > 0));